-- Nova versão dos exemplos resolvidos da Lei 15.358/2026 (Lei antifacção).
-- Substitui os 2 casos curtos por 7 casos concretos, conferidos no texto oficial do Planalto em 08/10/2026
-- (arts. 2º, 3º, 4º, 5º, 9º, 30, 36, 37 e 44; Lei 15.358 não altera a Lei 12.850).
-- Entra `under_review`: a versão anterior continua visível até o admin ativar esta no painel
-- (Biblioteca) ou por UPDATE com o seu usuário. Não define reviewed_by/reviewed_at.
-- O hash do texto é calculado a partir do material já gravado no banco.
begin;

insert into public.study_material_enrichments
  (id, material_slug, version, source_body_sha256, content, sources, checked_at, status)
select
  '3ef79962-afe2-5b02-86ae-ef25e2ab2314'::uuid,
  m.slug,
  '2026-10-08',
  encode(sha256(convert_to(m.body_md, 'UTF8')), 'hex'),
  $json${"illustrations": [{"kind": "flow", "title": "Como classificar um fato da Lei 15.358", "caption": "Siga a ordem; cada caso abaixo trabalha uma das perguntas.", "nodes": ["O grupo é facção? (3+ pessoas, violência ou ameaça para controlar território)", "Quem é o agente: integrante (art. 2º) ou apoiador (art. 3º)?", "Quais as consequências: pena, hediondo, execução e patrimônio", "Há reflexo em Drogas e Armas? (arts. 36 e 37)", "O fato é posterior a 25/03/2026?"]}], "cases": [{"id": "anti-1", "title": "Três pessoas já podem ser uma \"facção\"?", "scenario": "Marcos, Léo e Tati andam armados pelo bairro. Eles exigem dinheiro dos comerciantes e dizem que quem não pagar terá a loja destruída. Na prática, só eles mandam na rua.", "question": "O grupo se encaixa no conceito de facção criminosa da Lei 15.358?", "steps": ["O conceito está no art. 2º, § 2º: \"organização criminosa ultraviolenta, denominada facção criminosa\" é o agrupamento de 3 ou mais pessoas que emprega violência, grave ameaça ou coação para impor controle territorial ou social, intimidar populações ou autoridades, ou atacar serviços e infraestrutura essenciais.", "Número: são 3 pessoas, e a lei aceita 3. (Na Lei 12.850 o mínimo é 4. Os números são diferentes porque as leis são diferentes.)", "Conduta: o grupo usa ameaça e armas para impor controle sobre o bairro e intimidar a população. É exatamente o tipo de finalidade que o § 2º descreve."], "conclusion": "Sim. Três pessoas que usam violência ou ameaça para controlar um território se encaixam no conceito de facção do art. 2º, § 2º. Cada integrante ainda precisa ter praticado uma das condutas listadas no art. 2º para responder pelo crime de domínio social estruturado.", "variation": {"scenario": "E se Marcos, Léo e Tati fossem apenas três amigos que conversam no bar, sem ameaça, sem violência e sem controle de nada?", "answer": "Não é facção. Ter 3 pessoas não basta: a lei exige o emprego de violência, grave ameaça ou coação com as finalidades do § 2º."}, "pitfall": "Achar que \"3 pessoas\" já resolve. O número é só o primeiro filtro; a violência com finalidade de controle é o que caracteriza a facção.", "articles": ["Art. 2"]}, {"id": "anti-2", "title": "Emprestar o galpão: art. 2º ou art. 3º?", "scenario": "Paulo não participa de ataques nem de cobranças. Ele é dono de um galpão e, sabendo que a facção da região guarda armas ali para os ataques, aceita receber dinheiro para deixar o espaço à disposição do grupo.", "question": "Paulo responde pelo crime do art. 2º (pena de 20 a 40 anos) ou por outro crime?", "steps": ["O art. 2º é praticado por \"integrante\" da organização ultraviolenta, grupo paramilitar ou milícia. Paulo apenas cede um espaço, e não executa as condutas do art. 2º.", "O art. 3º trata de quem favorece o domínio social estruturado. Uma das condutas é ceder local ou bem para a prática dos atos do art. 2º, e outra é adquirir ou guardar arma ou explosivo para essa finalidade.", "A pena do art. 3º é reclusão de 12 a 20 anos e multa. É uma pena menor que a do art. 2º (20 a 40 anos), mas ainda é pena de crime hediondo (art. 4º)."], "conclusion": "Paulo responde, em tese, pelo art. 3º (favorecimento), e não pelo art. 2º. O ponto decisivo é o papel dele: apoiador, e não integrante que executa as condutas do art. 2º.", "variation": {"scenario": "E se, além de ceder o galpão, Paulo também participasse dos ataques como integrante do grupo?", "answer": "Aí ele passa a se enquadrar no art. 2º, como integrante, sem prejuízo de analisar o art. 3º. Quem pratica as condutas do art. 2º responde pela pena mais grave."}, "pitfall": "Tratar todo mundo que ajuda a facção como se fosse integrante. A lei separa quem pratica o domínio (art. 2º) de quem o favorece (art. 3º), com penas diferentes.", "articles": ["Art. 2", "Art. 3", "Art. 4"]}, {"id": "anti-3", "title": "O chefe foi preso: onde cumpre pena e a família recebe auxílio?", "scenario": "Rogério, apontado como líder de uma facção, foi condenado pelo art. 2º da Lei 15.358. A família quer saber se ele vai para a cadeia da cidade e se os dependentes terão auxílio-reclusão.", "question": "O que a lei diz sobre o local de cumprimento e sobre o auxílio-reclusão?", "steps": ["Local: o art. 2º, § 7º diz que quem tem indícios de liderança cumpre pena em presídio federal de segurança máxima, conforme a Lei 11.671/2008.", "Auxílio-reclusão: o art. 2º, § 6º veda o benefício (art. 80 da Lei 8.213/1991) aos dependentes de quem está preso por esse crime. O art. 30 da própria Lei 15.358 reafirma a vedação.", "Benefícios penais: o art. 2º, § 4º torna o crime insuscetível de anistia, graça, indulto e fiança e veda o livramento condicional. Por ser hediondo (art. 4º), a progressão de regime segue regras mais rígidas da LEP."], "conclusion": "Rogério vai para presídio federal de segurança máxima, a família não recebe auxílio-reclusão e ele não tem direito a fiança, indulto nem livramento condicional.", "variation": {"scenario": "E se Rogério fosse apenas um integrante comum, sem nenhum indício de liderança?", "answer": "A regra do presídio federal (§ 7º) mira quem tem indícios de liderança. A vedação do auxílio-reclusão e a proibição de anistia, indulto e fiança continuam valendo para o crime."}, "pitfall": "Pensar que as vedações se aplicam só ao chefe. Apenas o § 7º (presídio federal) depende de indícios de liderança; as outras vedações valem para o crime.", "articles": ["Art. 2", "Art. 4", "Art. 30"]}, {"id": "anti-4", "title": "Passaram 90 dias: o preso tem de ser solto?", "scenario": "O delegado instaurou inquérito contra um investigado preso por crime da Lei 15.358. Passados 90 dias, o inquérito ainda não terminou, e a defesa pede a soltura automática.", "question": "O atraso obriga a soltar o investigado?", "steps": ["Prazo: o art. 5º fixa 90 dias para concluir o inquérito com indiciado preso e 270 dias com indiciado solto, prorrogáveis por igual período.", "Consequência do atraso: o art. 5º, § 4º diz que o descumprimento desses prazos não gera relaxamento automático da prisão nem liberdade automática.", "O juiz avalia o caso concreto: se a prisão continua necessária, se o atraso é justificável e se a investigação segue em andamento."], "conclusion": "Não. O prazo existe e deve ser respeitado, mas passar de 90 dias não solta o preso por si só. A prisão é reavaliada pelo juiz no caso concreto.", "variation": {"scenario": "E se o inquérito já tivesse ultrapassado também a prorrogação, sem nenhuma diligência feita?", "answer": "A regra de não haver soltura automática continua, mas a falta de justificativa pesa na reavaliação da prisão pelo juiz. O § 4º dispensa o automatismo, não o controle judicial."}, "pitfall": "Concluir que \"prazo estourado = soltura\". A lei afasta esse automatismo, mas não impede o controle judicial da prisão.", "articles": ["Art. 5"]}, {"id": "anti-5", "title": "Bloqueio de bens: quem prova a origem e quem protege o terceiro?", "scenario": "Em investigação sobre uma facção, o juiz bloqueia a conta e um carro de Rita, dona de uma padaria, por indícios de que parte do dinheiro dela vem do grupo. Rita diz que o dinheiro é da padaria. Outro bloqueio atinge um imóvel que Davi comprou do investigado sem saber da origem do dinheiro.", "question": "Rita e Davi podem reagir? E o patrimônio pode ser perdido sem condenação?", "steps": ["Medida cautelar: o art. 9º permite ao juiz decretar medidas assecuratórias, como bloqueio de bens e de ativos digitais. O contraditório pode ser adiado (§ 1º), por isso Rita pode ser surpreendida pela decisão.", "Defesa de Rita: o investigado tem 10 dias para comprovar a origem lícita dos bens. Comprovada a origem, o juiz libera os bens (com exceção de armas de fogo).", "Terceiro de boa-fé: o art. 9º, § 9º afasta o perdimento quando há boa-fé do terceiro. Davi deve demonstrar que não sabia e agiu de boa-fé.", "Perdimento sem condenação: o art. 9º, § 8º prevê o perdimento extraordinário, independente de condenação, quando a origem ilícita for clara."], "conclusion": "Rita e Davi podem reagir: Rita comprovando a origem lícita em 10 dias e Davi demonstrando boa-fé. O perdimento sem condenação só vale quando a origem ilícita é clara.", "variation": {"scenario": "E se Rita não apresentasse nenhuma prova da origem lícita e os indícios de origem ilícita fossem claros?", "answer": "Aí o juiz pode aplicar o perdimento extraordinário (§ 8º), mesmo sem condenação."}, "pitfall": "Imaginar que bloquear é o mesmo que perder. O bloqueio é cautelar e reversível; o perdimento exige origem ilícita clara ou, depois, medida definitiva (art. 11) ou ação civil de perdimento.", "articles": ["Art. 9", "Art. 11"]}, {"id": "anti-6", "title": "Tráfico com pistola por integrante de facção", "scenario": "Bruno é integrante de uma facção descrita no art. 2º da Lei 15.358. Ele é preso vendendo drogas e portando uma pistola, em ação ligada ao controle do território do grupo.", "question": "Que regras novas da Lei 15.358 mudam a situação de Bruno em relação à Lei de Drogas e ao Estatuto do Desarmamento?", "steps": ["Drogas: o art. 36 da Lei 15.358 acrescentou o art. 40-A à Lei 11.343/2006. As penas dos crimes dos arts. 33 a 37 são aplicadas em dobro quando o autor é integrante de organização ultraviolenta, grupo paramilitar ou milícia, no contexto do art. 2º.", "Arma e tráfico juntos: o parágrafo único do art. 40-A manda aplicar concurso material (art. 69 do CP) quando há emprego de arma de fogo. As penas somam-se, mesmo que a arma não esteja diretamente ligada ao tráfico.", "Desarmamento: o art. 37 acrescentou o art. 21-A à Lei 10.826/2003. Nos crimes dos arts. 12, 14 e 16 (posse irregular, porte ilegal e posse ou porte de arma de uso restrito), a pena aumenta em 2/3 se houver concurso com crime de drogas, ligação com o tráfico ou uso da arma para garantir a mercancia."], "conclusion": "A pena do tráfico de Bruno é dobrada (art. 40-A), a arma entra em concurso material e o crime de arma sofre o aumento de 2/3 do art. 21-A. Sempre conferir o contexto: tudo depende de ele ser integrante e de o fato estar no contexto do art. 2º.", "variation": {"scenario": "E se Bruno fosse traficante sem nenhuma ligação com facção, grupo paramilitar ou milícia?", "answer": "O art. 40-A não se aplica, porque exige o contexto do art. 2º. Já o aumento do art. 21-A pode incidir se a arma estiver ligada ao tráfico. Confira o texto de cada artigo."}, "pitfall": "Aplicar o dobro da pena a qualquer traficante. O art. 40-A só vale para integrante de organização ultraviolenta, grupo paramilitar ou milícia, no contexto do art. 2º.", "articles": ["Art. 36", "Art. 37"]}, {"id": "anti-7", "title": "O fato foi em fevereiro: a lei nova vale?", "scenario": "Em 10/02/2026, um grupo praticou um ataque que hoje se enquadraria no art. 2º da Lei 15.358. A denúncia só foi oferecida em maio.", "question": "Dá para condenar o grupo com a pena de 20 a 40 anos do art. 2º?", "steps": ["Vigência: o art. 44 diz que a lei entra em vigor na data da publicação, 25/03/2026, sem vacatio legis.", "Retroatividade: a lei penal mais grave não retroage para prejudicar o acusado (art. 5º, XL, da Constituição). Vale para fatos praticados a partir da vigência.", "Data do fato: o ataque foi em 10/02/2026, antes da vigência. A data do fato é a que importa, e não a da denúncia."], "conclusion": "Não. O fato é anterior à vigência da lei, então o art. 2º da Lei 15.358 não se aplica. O fato será analisado pela lei vigente na época.", "variation": {"scenario": "E se o ataque tivesse sido em 10/04/2026?", "answer": "Aí a lei já estava em vigor e o art. 2º pode ser aplicado, desde que presentes os demais requisitos."}, "pitfall": "Olhar a data da denúncia ou da prisão. Para a lei penal mais grave, vale a data do fato.", "articles": ["Art. 44"]}]}$json$::jsonb,
  $json$[{"title": "Lei 15.358/2026 — texto oficial (arts. 2º a 5º, 9º, 30, 36, 37 e 44)", "url": "https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15358.htm", "checked_at": "2026-10-08T02:35:41Z"}]$json$::jsonb,
  '2026-10-08T02:35:41Z',
  'under_review'
from public.study_materials m
where m.slug = 'legislacao-antifaccao-marco-legal'
on conflict (material_slug, version) do nothing;

commit;
